        ///<summary>
        ///Reclaim terminal consensus boxes without deleting the historical Guild proposal.
        ///
        ///Every listed vote receipt's storage returns to whoever paid it, the voter unless someone else
        ///funded the vote; the ballot storage returns to the proposal's payer.
        ///Approved ballots stay until execution or cancellation, since policies read the approving
        ///ballot while applying consensus actions.
        ///</summary>
        /// <param name="proposalID"> </param>
        /// <param name="voters"> </param>
        public async Task<ulong> CleanupProposalConsensus(ulong proposalID, Algorand.Address[] voters, Account _tx_sender, ulong? _tx_fee, string _tx_note = "", ulong _tx_roundValidity = 1000, List<BoxRef>? _tx_boxes = null, List<Transaction>? _tx_transactions = null, List<ulong>? _tx_assets = null, List<ulong>? _tx_apps = null, List<Address>? _tx_accounts = null, AVM.ClientGenerator.Core.OnCompleteType _tx_callType = AVM.ClientGenerator.Core.OnCompleteType.NoOp)
        {
            _tx_boxes ??= new List<BoxRef>();
            _tx_transactions ??= new List<Transaction>();
            _tx_assets ??= new List<ulong>();
            _tx_apps ??= new List<ulong>();
            _tx_accounts ??= new List<Address>();
            byte[] abiHandle = { 181, 122, 30, 205 };
            var proposalIDAbi = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64(); proposalIDAbi.From(proposalID);
            var votersAbi = new AVM.ClientGenerator.ABI.ARC4.Types.VariableArray<AVM.ClientGenerator.ABI.ARC4.Types.Address>("address"); votersAbi.From(voters);

            var result = await base.CallApp(new List<object> { abiHandle, proposalIDAbi, votersAbi }, _tx_fee: _tx_fee, _tx_callType: _tx_callType, _tx_roundValidity: _tx_roundValidity, _tx_note: _tx_note, _tx_sender: _tx_sender, _tx_transactions: _tx_transactions, _tx_apps: _tx_apps, _tx_assets: _tx_assets, _tx_accounts: _tx_accounts, _tx_boxes: _tx_boxes);
            var lastLogBytes = result.Last();
            if (lastLogBytes.Length < 4 || lastLogBytes[0] != 21 || lastLogBytes[1] != 31 || lastLogBytes[2] != 124 || lastLogBytes[3] != 117) throw new Exception("Invalid ABI handle");
            var lastLogReturnData = lastLogBytes.Skip(4).ToArray();
            var returnValueObj = new AVM.ClientGenerator.ABI.ARC4.Types.UInt64();
            returnValueObj.Decode(lastLogReturnData);
            return BitConverter.ToUInt64(ReverseIfLittleEndian(lastLogReturnData), 0);

        }

